import React, { useState, useEffect } from 'react';

function Analytics() {
  const [data, setData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [filter, setFilter] = useState("ALL");

  useEffect(() => {
    fetch('http://localhost:5000/api/analytics')
      .then(res => res.json())
      .then(d => {
        setData(d);
        setLoading(false);
      })
      .catch(err => {
        console.error("Fetch error:", err);
        setLoading(false);
      });
  }, []);

  if (loading) return <p>Loading Analytics...</p>;
  if (!data) return <p style={{ color: 'red' }}>Backend not reachable.</p>;

  // ✅ Synchronized Filter Logic
  const filteredUAVs = (data.uavs || []).filter(u => {
    if (filter === "ALL") return true;
    return u.status === filter;
  });

  return (
    <div style={{ padding: '20px', fontFamily: 'sans-serif' }}>
      <h2>Quality Analytics Dashboard</h2>

      {/* KPI CARDS */}
      <div style={{ display: 'flex', gap: '15px', marginBottom: '30px' }}>
        {[
          { label: 'Total', value: data.total, color: '#333', type: 'ALL' },
          { label: 'Passed', value: data.passed, color: 'green', type: 'Pass' },
          { label: 'Failed', value: data.failed, color: 'red', type: 'Fail' },
          { label: 'In Progress', value: data.inProgress, color: 'orange', type: 'In Progress' },
        ].map(k => (
          <div
            key={k.label}
            onClick={() => setFilter(k.type)}
            style={{
              border: `2px solid ${k.color}`,
              padding: '20px',
              borderRadius: '10px',
              cursor: 'pointer',
              background: filter === k.type ? '#f0f0f0' : 'white',
              flex: 1,
              textAlign: 'center'
            }}
          >
            <h1 style={{ color: k.color, margin: 0 }}>{k.value}</h1>
            <p style={{ fontWeight: 'bold' }}>{k.label}</p>
          </div>
        ))}
      </div>

      <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '30px' }}>
        {/* LEFT: UAV LIST */}
        <section>
          <h3>UAV Status List ({filter})</h3>
          <table border="1" width="100%" style={{ borderCollapse: 'collapse', textAlign: 'left' }}>
            <thead style={{ background: '#eee' }}>
              <tr>
                <th style={{ padding: '10px' }}>UAV ID</th>
                <th style={{ padding: '10px' }}>Result</th>
              </tr>
            </thead>
            <tbody>
              {filteredUAVs.length === 0 ? (
                <tr><td colSpan="2" style={{ padding: '10px' }}>No records match this filter</td></tr>
              ) : (
                filteredUAVs.map(u => (
                  <tr key={u.id}>
                    <td style={{ padding: '10px' }}>{u.id}</td>
                    <td style={{ padding: '10px', color: u.status === 'Pass' ? 'green' : u.status === 'Fail' ? 'red' : 'orange' }}>
                      {u.status}
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </section>

        {/* RIGHT: DATA ANALYTICS (Stage Defects) */}
        <section>
          <h3>Production Line Bottlenecks</h3>
          <p><small>Analyzing defects across the 7 stages of assembly:</small></p>
          {data.stageData.map(stage => (
            <div key={stage.name} style={{ marginBottom: '10px' }}>
              <div style={{ display: 'flex', justifyContent: 'space-between' }}>
                <span>{stage.name}</span>
                <span><b>{stage.defects} Defects</b></span>
              </div>
              <div style={{ background: '#eee', height: '10px', borderRadius: '5px' }}>
                <div style={{ 
                  background: stage.defects > 5 ? 'red' : 'blue', 
                  width: `${Math.min(stage.defects * 10, 100)}%`, 
                  height: '100%', 
                  borderRadius: '5px',
                  transition: 'width 0.5s'
                }}></div>
              </div>
            </div>
          ))}
        </section>
      </div>
    </div>
  );
}

export default Analytics;
